import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        long n = nextLong();
        String s = next();
        long gap = nextLong();
        long[] cnt = new long[26];
        for (int i = 0; i < s.length(); i++) cnt[s.charAt(i) - 'a']++;
        long f = 0, c = 0;
        for (long v : cnt) f = Math.max(f, v);
        for (long v : cnt) if (v == f) c++;
        // Lower bounds: all requests, and f-1 full rounds of length gap+1 plus the c most frequent regions.
        System.out.println(Math.max(s.length(), (f - 1) * (gap + 1) + c));
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"slices"
)

func main() {
	data, _ = io.ReadAll(os.Stdin)
	nextInt()
	s := nextToken()
	gap := nextInt()
	var cnt [26]int64
	for _, ch := range s {
		cnt[ch-'a']++
	}
	f := slices.Max(cnt[:])
	var c int64
	for _, v := range cnt {
		if v == f {
			c++
		}
	}
	// Lower bounds: all requests, and f-1 full rounds of length gap+1 plus the c most frequent regions.
	fmt.Println(max(int64(len(s)), (f-1)*(gap+1)+c))
}

var data []byte
var pos int

func skipSpace() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextToken() []byte {
	skipSpace()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	skipSpace()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}
